/**
 * Builds supabase/functions/_shared/skillClusters.ts from the reviewed CSV
 * scripts/dslm/data/skill-clusters.csv (D10 stage 2, option A, read-side clusters).
 *
 * Only scenario 2 rows with HIGH or MED confidence are used (scenario 2 is the
 * single-partition high+medium run; its LOW rows are oversized or task-type families
 * and are never used for mastery pooling). The CSV holds no names or student ids,
 * only skill key signatures and counts. Output is deterministic (sorted, no dates).
 *
 *   node scripts/dslm/build-skill-clusters.mjs           write the generated file
 *   node scripts/dslm/build-skill-clusters.mjs --check   exit 1 when the file is stale
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
export const CSV_PATH = path.join(here, 'data', 'skill-clusters.csv');
export const OUT_PATH = path.join(here, '..', '..', 'supabase', 'functions', '_shared', 'skillClusters.ts');

const USED_SCENARIO = '2';
const USED_CONFIDENCE = new Set(['HIGH', 'MED']);

/** Same shape as skillLabel() in _shared/skillLabels.ts: `category: words`. */
function labelFor(category, rest) {
  const text = rest.replace(/[._]+/g, ' ').replace(/\s+/g, ' ').replace(/[<>]/g, '').trim().slice(0, 60);
  return `${category}: ${text}`;
}

export function parseRows(csvText) {
  const lines = csvText.replace(/\r/g, '').split('\n').filter((l) => l.trim());
  const header = lines[0].split(',');
  const col = (name) => header.indexOf(name);
  const idx = { scenario: col('scenario'), id: col('cluster_id'), conf: col('confidence'), cat: col('category'), key: col('key'), events: col('events') };
  if (Object.values(idx).some((i) => i < 0)) throw new Error('skill-clusters.csv: unexpected header');
  return lines.slice(1).map((l) => {
    const p = l.split(',');
    return { scenario: p[idx.scenario], id: p[idx.id], conf: p[idx.conf], category: p[idx.cat], key: p[idx.key], events: Number(p[idx.events]) || 0 };
  });
}

export function buildClusters(csvText) {
  const byId = new Map();
  for (const r of parseRows(csvText)) {
    if (r.scenario !== USED_SCENARIO || !USED_CONFIDENCE.has(r.conf)) continue;
    const g = byId.get(r.id) || { category: r.category, members: [] };
    g.members.push({ rest: r.key, events: r.events });
    byId.set(r.id, g);
  }
  const seen = new Set();
  const clusters = [];
  for (const g of byId.values()) {
    if (g.members.length < 2) continue;
    // Representative: most events, ties alphabetical. Its canonical key becomes the cluster key.
    const rep = [...g.members].sort((a, b) => b.events - a.events || (a.rest < b.rest ? -1 : 1))[0];
    const members = g.members.map((m) => `${g.category}|${m.rest}`).sort();
    for (const m of members) {
      if (seen.has(m)) throw new Error(`skill-clusters.csv: key in two clusters: ${m}`);
      seen.add(m);
    }
    clusters.push({ key: `${g.category}|${rep.rest}`, label: labelFor(g.category, rep.rest), members });
  }
  clusters.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  return clusters;
}

export function buildSkillClustersSource(csvText) {
  const clusters = buildClusters(csvText);
  const memberCount = clusters.reduce((a, c) => a + c.members.length, 0);
  const body = clusters
    .map((c) => `  { key: ${JSON.stringify(c.key)}, label: ${JSON.stringify(c.label)}, members: ${JSON.stringify(c.members)} },`)
    .join('\n');
  return `// GENERATED by scripts/dslm/build-skill-clusters.mjs from scripts/dslm/data/skill-clusters.csv. Do not edit.
// ${clusters.length} reviewed HIGH/MED clusters, ${memberCount} canonical member keys (D10 stage 2, option A).

export interface SkillCluster {
  /** Cluster key = canonical key of its most frequent member. */
  key: string;
  /** Human label, \`category: words\`. */
  label: string;
  /** Canonical keys (\`category|rest\`) pooled into this cluster. */
  members: readonly string[];
}

export const SKILL_CLUSTERS: readonly SkillCluster[] = [
${body}
];
`;
}

function main() {
  const source = buildSkillClustersSource(fs.readFileSync(CSV_PATH, 'utf8'));
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(OUT_PATH) ? fs.readFileSync(OUT_PATH, 'utf8') : '';
    if (current !== source) {
      console.error('skillClusters.ts is stale: run node scripts/dslm/build-skill-clusters.mjs');
      process.exit(1);
    }
    return;
  }
  fs.writeFileSync(OUT_PATH, source);
  console.log(`wrote ${path.relative(process.cwd(), OUT_PATH)}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
